import { test, expect } from "../helpers/system-control-browser";
import AxeBuilder from "@axe-core/playwright";

test("landing: theme reveal keeps the old theme outside the circle without flashing", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/");
  await expect(
    page.getByRole("button", { name: "Switch to light theme" }),
  ).toBeVisible();
  await page.evaluate(() => {
    const animate = Element.prototype.animate;
    Element.prototype.animate = function (keyframes, options) {
      const animation = animate.call(this, keyframes, options);
      if (
        typeof options === "object" &&
        options.pseudoElement === "::view-transition-new(root)"
      ) {
        animation.pause();
        // Hold just before the active interval to catch a pre-animation flash.
        animation.currentTime = -1;
      }
      return animation;
    };
  });
  const viewport = page.viewportSize()!;
  const clip = { x: 4, y: viewport.height - 6, width: 2, height: 2 };
  const cornerColor = async () => {
    const png = (await page.screenshot({ clip })).toString("base64");
    return page.evaluate(async (png) => {
      const image = new Image();
      image.src = `data:image/png;base64,${png}`;
      await image.decode();
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 1;
      const context = canvas.getContext("2d")!;
      context.drawImage(image, 0, 0, 1, 1);
      return [...context.getImageData(0, 0, 1, 1).data].slice(0, 3);
    }, png);
  };
  for (const theme of ["light", "dark"] as const) {
    const oldCorner = await cornerColor();
    const expectOldCorner = async () => {
      const color = await cornerColor();
      for (let channel = 0; channel < 3; channel++) {
        // Mobile snapshot rasterization may round a channel by one level.
        expect(
          Math.abs(color[channel] - oldCorner[channel]),
        ).toBeLessThanOrEqual(2);
      }
    };
    await page
      .getByRole("button", {
        name: `Switch to ${theme} theme`,
        exact: true,
      })
      .click();
    await expect
      .poll(() =>
        page.evaluate(() =>
          document
            .getAnimations()
            .some(
              (animation) =>
                (animation.effect as KeyframeEffect).pseudoElement ===
                  "::view-transition-new(root)" &&
                animation.playState === "paused",
            ),
        ),
      )
      .toBe(true);
    expect(
      await page.evaluate(
        () =>
          document
            .getAnimations()
            .find(
              (animation) =>
                (animation.effect as KeyframeEffect).pseudoElement ===
                "::view-transition-new(root)",
            )!
            .effect!.getTiming().duration,
      ),
    ).toBe(480);
    // The DOM already has the new palette, but the first rendered frame must
    // still show the old theme outside the zero-radius circle.
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
    await expectOldCorner();
    await page.evaluate(() => {
      const animation = document
        .getAnimations()
        .find(
          (animation) =>
            (animation.effect as KeyframeEffect).pseudoElement ===
            "::view-transition-new(root)",
        )!;
      animation.currentTime = 240;
    });
    await expectOldCorner();
    await page.evaluate(() => {
      document
        .getAnimations()
        .find(
          (animation) =>
            (animation.effect as KeyframeEffect).pseudoElement ===
            "::view-transition-new(root)",
        )!
        .finish();
    });
    await expect(page.locator("html")).not.toHaveAttribute("data-theme-reveal");
    const newCorner = await cornerColor();
    for (let channel = 0; channel < 3; channel++) {
      expect(Math.abs(newCorner[channel] - oldCorner[channel])).toBeGreaterThan(
        100,
      );
    }
    expect(
      await page.evaluate(() =>
        document.documentElement.style.getPropertyValue(
          "--theme-reveal-origin",
        ),
      ),
    ).toBe("");
  }
});

for (const theme of ["dark", "light"] as const) {
  test(`landing: ${theme} accessibility, responsiveness, and shared sign-in`, async ({
    page,
  }) => {
    await page.emulateMedia({ reducedMotion: "reduce", colorScheme: "light" });
    await page.addInitScript(
      (value) => localStorage.setItem("mailloop-theme", value),
      theme,
    );
    await page.goto("/");
    await expect(page).toHaveTitle(
      "Mailloop — Personalized outreach, made easy",
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", theme);

    for (const width of [
      320, 375, 390, 639, 640, 768, 1024, 1280, 1366, 1440, 1672,
    ]) {
      await page.setViewportSize({ width, height: 900 });
      const clearance = await page.evaluate(() => {
        const navbar = document
          .querySelector(".landing-navbar-pill")!
          .getBoundingClientRect();
        const heroContent = document
          .querySelector(".landing-hero > div")!
          .getBoundingClientRect();
        const card = document
          .querySelector(".landing-dashboard-perspective")!
          .getBoundingClientRect();
        return (
          (innerWidth < 640
            ? heroContent.top
            : Math.min(heroContent.top, card.top)) - navbar.bottom
        );
      });
      expect(clearance, `hero clearance at ${width}px`).toBeGreaterThanOrEqual(
        12,
      );
      expect(
        await page.evaluate(
          () => document.documentElement.scrollWidth <= innerWidth,
        ),
      ).toBe(true);
      await expect(page.locator(".landing-dashboard-perspective")).toBeVisible({
        visible: width >= 640,
      });
      if (width >= 640) {
        await expect(
          page.getByRole("img", { name: /Example batch/ }),
        ).toHaveAttribute(
          "aria-label",
          "Example batch: 10 of 10 emails sent, 0 queued, 0 failed",
        );
      }
      const shortTargets = await page
        .locator(".landing a, .landing button")
        .evaluateAll((elements) =>
          elements
            // Inline prose links use WCAG's inline target-size exception.
            .filter(
              (element) =>
                !element.closest(".landing-closing p, .pricing-foot"),
            )
            .filter(
              (element) =>
                element.getClientRects().length > 0 &&
                element.getBoundingClientRect().height < 44,
            )
            .map((element) => element.textContent),
        );
      expect(shortTargets).toEqual([]);
      expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
    }
    const actions = await page
      .locator(".landing form")
      .evaluateAll((forms) =>
        forms.map((form) =>
          form.querySelector('input[name^="$ACTION_"]')?.getAttribute("name"),
        ),
      );
    expect(actions).toHaveLength(5);
    expect(actions[0]).toBeTruthy();
    expect(actions[0]).toBe(actions[1]);
    expect(actions[0]).toBe(actions[2]);
    expect(actions[0]).toBe(actions[3]);
    expect(actions[4]).toBeTruthy();
    expect(actions[4]).not.toBe(actions[0]);
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.getByRole("link", { name: "How it works" }).click();
    await expect(page).toHaveURL(/#how$/);
    await expect(page.locator("#how")).toBeInViewport();
    await page.getByRole("link", { name: "Features", exact: true }).click();
    await expect(page).toHaveURL(/#features$/);
    await expect(page.locator("#features article")).toHaveCount(6);
    await page.goto("/?error=AccessDenied");
    await expect(page.locator(".landing").getByRole("alert")).toContainText(
      "Google sign-in could not complete",
    );
  });
}

test("landing: fixed navigation, mobile menu, section links, and keyboard focus", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/");
  const nav = page.locator(".landing-navbar");
  await page.setViewportSize({ width: 375, height: 812 });
  await expect(nav).toHaveCSS("position", "fixed");
  await expect(
    page.getByRole("button", { name: "Sign in" }).first(),
  ).toBeHidden();
  const menu = page.getByRole("button", { name: "Open menu" });
  await menu.focus();
  await expect(menu).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(
    page.getByRole("button", { name: "Close menu" }),
  ).toHaveAttribute("aria-expanded", "true");
  await expect(
    page
      .getByRole("navigation", { name: "Mobile navigation" })
      .getByRole("button", { name: "Sign in" }),
  ).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(
    page.getByRole("navigation", { name: "Mobile navigation" }),
  ).toBeHidden();
  await menu.click();
  await page
    .getByRole("navigation", { name: "Mobile navigation" })
    .getByRole("link", { name: "Pricing" })
    .click();
  await expect(page).toHaveURL(/#pricing$/);
  await expect(nav).toHaveAttribute("data-compact", "true");
  await expect(
    page.getByRole("navigation", { name: "Mobile navigation" }),
  ).toBeHidden();
  await page.setViewportSize({ width: 700, height: 812 });
  await expect(
    nav.locator("form").first().getByRole("button", { name: "Sign in" }),
  ).toBeVisible();
  await menu.click();
  await expect(
    page
      .getByRole("navigation", { name: "Mobile navigation" })
      .getByRole("button", { name: "Sign in" }),
  ).toBeVisible();
  await page.setViewportSize({ width: 1280, height: 900 });
  // Re-anchor after the desktop layout changes the sections' document positions.
  await page
    .getByRole("navigation", { name: "Main navigation" })
    .getByRole("link", { name: "Pricing" })
    .click();
  await expect(
    page
      .getByRole("navigation", { name: "Main navigation" })
      .getByRole("link", { name: "Pricing" }),
  ).toHaveAttribute("aria-current", "location");
  await expect(
    page.getByRole("navigation", { name: "Mobile navigation" }),
  ).toBeHidden();
});

test("landing: dark first paint, keyboard switch, persistence, and storage sync", async ({
  page,
}) => {
  await page.emulateMedia({ colorScheme: "light", reducedMotion: "reduce" });
  await page.addInitScript(() => {
    const seen: string[] = [];
    Object.assign(window, { landingThemes: seen });
    new MutationObserver(() => {
      const theme = document.documentElement?.dataset.theme;
      if (theme) seen.push(theme);
    }).observe(document, {
      attributes: true,
      attributeFilter: ["data-theme"],
      subtree: true,
    });
  });
  await page.goto("/");
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  expect(
    await page.evaluate(
      () =>
        (window as typeof window & { landingThemes: string[] })
          .landingThemes[0],
    ),
  ).toBe("dark");
  const light = page.getByRole("button", { name: "Switch to light theme" });
  await light.focus();
  await page.keyboard.press("Enter");
  await expect(
    page.getByRole("button", { name: "Switch to dark theme" }),
  ).toBeVisible();
  await expect
    .poll(() =>
      page
        .locator('meta[name="theme-color"]')
        .evaluateAll((elements) =>
          elements.every(
            (element) => element.getAttribute("content") === "#faf9fe",
          ),
        ),
    )
    .toBe(true);
  await page.reload();
  await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
  await page.evaluate(() => {
    localStorage.setItem("mailloop-theme", "dark");
    dispatchEvent(
      new StorageEvent("storage", { key: "mailloop-theme", newValue: "dark" }),
    );
  });
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  await expect
    .poll(() =>
      page
        .locator('meta[name="theme-color"]')
        .evaluateAll((elements) =>
          elements.every(
            (element) => element.getAttribute("content") === "#0b0a14",
          ),
        ),
    )
    .toBe(true);
});

test("landing: eight-second progression, activity, purple ring, completion hold, and replay", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1366, height: 900 });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.clock.install({ time: new Date("2026-10-09T10:00:00Z") });
  await page.clock.pauseAt(new Date("2026-10-09T10:00:01Z"));
  await page.goto("/");
  const ring = page.getByRole("img", { name: /Example batch/ });
  const card = page.locator(".landing-batch");
  const arc = card.locator(".landing-progress-arc");
  await expect(
    page.getByRole("button", { name: "Pause batch animation" }),
  ).toBeVisible();
  await expect(ring).toHaveAttribute(
    "aria-label",
    /3 of 10 emails sent, 7 queued, 0 failed/,
  );
  await expect(card.locator(".landing-countdown-value")).toHaveText("00:08");
  await expect(card.locator('[data-status="delivered"]')).toHaveCount(3);
  await expect(card.locator('[data-status="sending"]')).toHaveCount(1);
  await expect(card.locator('[data-status="queued"]')).toHaveCount(1);
  const purple = await arc.evaluate(
    (element) => getComputedStyle(element).stroke,
  );
  expect(purple).toBe("rgb(177, 122, 249)");
  // Every second conserves the batch total and never introduces failures.
  for (let tick = 1; tick <= 8; tick++) {
    await page.clock.runFor(1000);
    const sent = Math.min(10, 3 + Math.floor((7 * tick) / 8));
    await expect(ring).toHaveAttribute(
      "aria-label",
      `Example batch: ${sent} of 10 emails sent, ${10 - sent} queued, 0 failed`,
    );
    await expect(card.locator(".landing-countdown-value")).toHaveText(
      `00:0${8 - tick}`,
    );
    await expect(arc).toHaveCSS("stroke", purple);
    const values = await card.locator(".landing-stat-value").allTextContents();
    expect(values.map(Number).reduce((a, b) => a + b, 0)).toBe(10);
    await expect(card.locator(".landing-batch-meta")).toContainText(
      `Elapsed 0m ${7 + tick}s`,
    );
    if (tick === 2) {
      await expect(card.locator('[data-status="delivered"]')).toHaveCount(4);
      await expect(card.locator('[data-status="sending"]')).toHaveCount(1);
    }
  }
  await expect(card).toHaveAttribute("data-done", "true");
  await expect(card.locator(".landing-status")).toHaveText("Batch completed");
  await expect(card.locator(".landing-completion-check")).toBeVisible();
  await expect(card.locator(".landing-countdown small")).toHaveText("All Sent");
  await expect(card.locator(".landing-countdown small")).toHaveCSS(
    "color",
    "rgb(115, 233, 175)",
  );
  await expect(card.locator(".landing-completion-check path")).toHaveCSS(
    "animation-name",
    "landing-completion-draw",
  );
  await expect(card.locator('[data-status="delivered"]')).toHaveCount(5);
  await expect(card.locator(".landing-activity li").first()).toContainText(
    "11s ago",
  );
  await page.clock.runFor(500);
  expect(
    await card
      .locator(".landing-bar-sent")
      .evaluate((el) => (el as HTMLElement).style.width),
  ).toBe("100%");
  await page.clock.runFor(3400);
  await expect(card).toHaveAttribute("data-done", "true");
  await page.clock.runFor(100);
  await expect(ring).toHaveAttribute(
    "aria-label",
    /3 of 10 emails sent, 7 queued, 0 failed/,
  );
  await expect(card).toHaveAttribute("data-reset", "true");
  await expect(card.locator(".landing-bar-sent")).toHaveCSS(
    "transition-duration",
    "0s",
  );
  await expect(card.locator('[data-status="delivered"]')).toHaveCount(3);
  await expect(arc).toHaveCSS("stroke", purple);
});

test("landing: timer ring advances between count updates and pauses in place", async ({
  page,
}) => {
  await page.setViewportSize({ width: 768, height: 900 });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.clock.install({ time: new Date("2026-10-09T10:00:00Z") });
  await page.clock.pauseAt(new Date("2026-10-09T10:00:01Z"));
  await page.goto("/");
  const card = page.locator(".landing-batch");
  const arc = card.locator(".landing-progress-arc");
  await card.evaluate((element) =>
    element.scrollIntoView({ behavior: "instant", block: "center" }),
  );
  await expect(card).toHaveAttribute("data-visible", "true");
  const length = () =>
    arc.evaluate((element) =>
      Number.parseFloat((element as SVGCircleElement).style.strokeDasharray),
    );
  const start = await length();
  await page.clock.runFor(100);
  const moving = await length();
  expect(moving).toBeGreaterThan(start);
  await expect(card.locator(".landing-countdown-value")).toHaveText("00:08");
  await page.getByRole("button", { name: "Pause batch animation" }).focus();
  await page.keyboard.press("Enter");
  const frozen = await length();
  await page.clock.runFor(500);
  expect(await length()).toBe(frozen);
  await page.getByRole("button", { name: "Resume batch animation" }).focus();
  await page.keyboard.press("Enter");
  await page.clock.runFor(100);
  expect(await length()).toBeGreaterThan(moving);
});

test("landing: pause, off-screen and hidden suspension, and reduced motion", async ({
  page,
}) => {
  await page.setViewportSize({ width: 1366, height: 900 });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.clock.install({ time: new Date("2026-10-09T10:00:00Z") });
  await page.clock.pauseAt(new Date("2026-10-09T10:00:01Z"));
  await page.goto("/");
  const ring = page.getByRole("img", { name: /Example batch/ });
  const card = page.locator(".landing-batch");
  await page.getByRole("button", { name: "Pause batch animation" }).focus();
  await page.keyboard.press("Enter");
  await expect(
    page.getByRole("button", { name: "Resume batch animation" }),
  ).toBeVisible();
  await page.clock.runFor(3000);
  await expect(ring).toHaveAttribute("aria-label", /3 of 10 emails sent/);
  await page.getByRole("button", { name: "Resume batch animation" }).focus();
  await page.keyboard.press("Enter");
  await expect(card).toHaveAttribute("data-paused", "false");
  await expect(card).toHaveAttribute("data-suspended", "false");
  await page.clock.runFor(2000);
  await expect(ring).toHaveAttribute("aria-label", /4 of 10 emails sent/);
  await page.locator("footer").scrollIntoViewIfNeeded();
  await expect(card).toHaveAttribute("data-visible", "false");
  const label = await ring.getAttribute("aria-label");
  await page.clock.runFor(3000);
  await expect(ring).toHaveAttribute("aria-label", label!);
  await card.scrollIntoViewIfNeeded();
  await expect(card).toHaveAttribute("data-visible", "true");
  await page.clock.runFor(1200);
  await expect(ring).not.toHaveAttribute("aria-label", label!);
  await page.evaluate(() => {
    Object.defineProperty(document, "hidden", {
      configurable: true,
      value: true,
    });
    document.dispatchEvent(new Event("visibilitychange"));
  });
  const beforeHidden = await ring.getAttribute("aria-label");
  await page.clock.runFor(3000);
  await expect(ring).toHaveAttribute("aria-label", beforeHidden!);
  await page.evaluate(() => {
    delete (document as unknown as { hidden?: boolean }).hidden;
    document.dispatchEvent(new Event("visibilitychange"));
  });
  await page.clock.runFor(1200);
  await expect(ring).not.toHaveAttribute("aria-label", beforeHidden!);
  await page.emulateMedia({ reducedMotion: "reduce" });
  await expect(card).toHaveAttribute("data-done", "true");
  await expect(
    page.getByRole("button", { name: /batch animation/ }),
  ).toHaveCount(0);
  await expect(card).toHaveCSS("animation-name", "none");
  await page.clock.runFor(30000);
  await expect(card).toHaveAttribute("data-done", "true");
});

