test("landing: dashboard hover keeps its tilt across status tiles", async ({
  page,
  isMobile,
}) => {
  test.skip(isMobile, "Hover requires a pointer device");
  await page.setViewportSize({ width: 1366, height: 900 });
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/");
  await page.getByRole("button", { name: "Pause batch animation" }).focus();
  await page.keyboard.press("Enter");
  const card = page.locator(".landing-batch");
  await expect(card).toHaveAttribute("data-paused", "true");
  const transform = await card.evaluate(
    (element) => getComputedStyle(element).transform,
  );
  const shadow = await card.evaluate(
    (element) => getComputedStyle(element).boxShadow,
  );
  await card.locator(".landing-batch-header").hover();
  await expect(card).toHaveCSS("translate", "0px -4px");
  await expect(card).toHaveCSS("transform", transform);
  await card.locator(".landing-stat").first().hover();
  await expect(card).toHaveCSS("translate", "0px -4px");
  await expect(card).toHaveCSS("transform", transform);
  await expect(card).toHaveCSS("box-shadow", shadow);
  await expect(card.locator(".landing-stat").first()).toHaveCSS(
    "transform",
    "none",
  );
  for (const stat of await card.locator(".landing-stat").all()) {
    await stat.hover();
    await expect(stat).toHaveCSS("translate", "0px -3px");
    await expect(stat).not.toHaveCSS("box-shadow", "none");
  }
  await page
    .getByRole("banner")
    .getByRole("link", { name: "Mailloop home" })
    .hover();
  await expect(card).toHaveCSS("translate", "0px");
});

test("landing: demo stays balanced at common desktop zoom layouts", async ({
  page,
}) => {
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/");
  for (const zoom of [1, 1.1, 1.2]) {
    await page.setViewportSize({
      width: Math.round(1440 / zoom),
      height: Math.round(900 / zoom),
    });
    const layout = await page.evaluate(() => {
      const heading = document.querySelector(".landing-hero h1")!;
      const hero = document.querySelector(".landing-hero")!;
      const stats = [...document.querySelectorAll(".landing-stat")];
      const rects = stats.map((stat) => stat.getBoundingClientRect());
      return {
        headingFits: heading.scrollWidth <= heading.clientWidth,
        heroFits: hero.getBoundingClientRect().right <= innerWidth + 1,
        noOverflow: document.documentElement.scrollWidth <= innerWidth + 1,
        equalCards:
          Math.max(...rects.map((rect) => rect.height)) -
            Math.min(...rects.map((rect) => rect.height)) <=
          1,
      };
    });
    expect(layout, `at ${Math.round(zoom * 100)}% zoom equivalent`).toEqual({
      headingFits: true,
      heroFits: true,
      noOverflow: true,
      equalCards: true,
    });
  }
});
